    // These three sets are disjoint (except possibly at boundaries where two sides are 0, but sides are positive integers so this can't happen).

    // So answer = total_ways - count(A >= B+C) - count(B >= A+C) - count(C >= A+B)

    // Let's compute count(A >= B+C) where A = a+da, B = b+db, C = c+dc, da+db+dc <= l, da,db,dc >= 0.
    // A >= B+C  =>  a+da >= b+db + c+dc  =>  da - db - dc >= b + c - a
    // Let k = b + c - a. We need da - db - dc >= k.
    // Also da + db + dc <= l.
    // Let x = da, y = db, z = dc.
    // x - y - z >= k  =>  x >= y + z + k
    // x + y + z <= l
    // x, y, z >= 0

    // Substitute x = y + z + k + t where t >= 0.
    // Then (y+z+k+t) + y + z <= l  =>  2y + 2z + t <= l - k
    // If l - k < 0, then count is 0.
    // Let L = l - k. We need 2y + 2z + t <= L, with y,z,t >= 0.
    // Let s = y + z. Then 2s + t <= L.
    // For a fixed s, t can range from 0 to L - 2s. Number of choices for t is L - 2s + 1.
    // Number of pairs (y,z) with y+z = s is s + 1.
    // So count = sum_{s=0}^{floor(L/2)} (s+1) * (L - 2s + 1)

    // Let's compute this sum efficiently.
    // Let M = floor(L/2).
    // Sum_{s=0}^{M} (s+1)(L+1 - 2s)
    // = (L+1) * Sum_{s=0}^{M} (s+1) - 2 * Sum_{s=0}^{M} s(s+1)
    // Sum_{s=0}^{M} (s+1) = (M+1)(M+2)/2
    // Sum_{s=0}^{M} s(s+1) = Sum_{s=0}^{M} (s^2 + s) = M(M+1)(2M+1)/6 + M(M+1)/2 = M(M+1)(2M+1+3)/6 = M(M+1)(2M+4)/6 = M(M+1)(M+2)/3

    // So count = (L+1) * (M+1)(M+2)/2 - 2 * M(M+1)(M+2)/3
    // = (M+1)(M+2) [ (L+1)/2 - 2M/3 ]
    // = (M+1)(M+2) [ (3(L+1) - 4M) / 6 ]

    // But we need to be careful with integer arithmetic. Let's compute it step by step.

    function countOneSide(base, other1, other2, l) {
        // Count number of (da, db, dc) >= 0 with da+db+dc <= l such that
        // (base + da) >= (other1 + db) + (other2 + dc)
        // da - db - dc >= other1 + other2 - base
        let k = other1 + other2 - base;
        let L = l - k;
        if (L < 0) return 0;

        let M = Math.floor(L / 2);
        if (M < 0) return 0;

        // Sum_{s=0}^{M} (s+1) * (L - 2s + 1)
        // Let's compute this directly or use the formula.
        // For safety with large numbers, let's use the formula carefully.
        // term1 = (L+1) * (M+1) * (M+2) / 2
        // term2 = 2 * M * (M+1) * (M+2) / 3
        // result = term1 - term2

        // To avoid floating point issues, let's compute:
        // result = (M+1)*(M+2) * [ (L+1)/2 - 2M/3 ]
        // = (M+1)*(M+2) * (3*(L+1) - 4*M) / 6

        let num = (M + 1) * (M + 2) * (3 * (L + 1) - 4 * M);
        // num should be divisible by 6
        return Math.floor(num / 6);
    }

    // Total ways: number of non-negative integer solutions to da+db+dc <= l
    // This is C(l+3, 3) = (l+1)(l+2)(l+3)/6
    let total = Math.floor((l + 1) * (l + 2) * (l + 3) / 6);

    let bad1 = countOneSide(a, b, c, l); // A >= B+C
    let bad2 = countOneSide(b, a, c, l); // B >= A+C
    let bad3 = countOneSide(c, a, b, l); // C >= A+B

    let answer = total - bad1 - bad2 - bad3;

    console.log(answer);
