    // Let's fix da. Then we need db + dc <= da - (b + c - a) = da - k, where k = b + c - a.
    // Also da + db + dc <= l => db + dc <= l - da.
    // So db + dc <= min(da - k, l - da), and db + dc >= 0.
    // Also da >= 0, and we need da - k >= 0 for there to be any solutions (if k > 0), or if k <= 0, then da - k >= 0 is always true for da >= 0.

    // Wait, if k <= 0, i.e., a >= b + c, then even with da=0, we have a >= b + c, so the condition a+da >= b+db+c+dc requires da >= db + dc + (b+c-a) = db + dc + k. Since k <= 0, this means da >= db + dc + k. If k is very negative, this is easy.

    // Let me just iterate da from 0 to l, and for each da, count the number of (db, dc) such that:
    // db + dc <= min(da - k, l - da)
    // db >= 0, dc >= 0
    // where k = b + c - a

    // The number of non-negative integer solutions to db + dc <= M is C(M+2, 2) = (M+1)(M+2)/2, if M >= 0. If M < 0, it's 0.

    // So Count1 = sum_{da=0}^{l} max(0, C(min(da - k, l - da) + 2, 2))

    // But l can be up to 3*10^5, so this is O(l) which is acceptable.

    function countWays(a, b, c, l) {
        // Count number of (da, db, dc) with da+db+dc <= l and a+da >= b+db + c+dc
        const k = b + c - a;
        let count = 0;
        for (let da = 0; da <= l; da++) {
