        // But we need l-s >= max(0, k+s)

        // If k >= 0:
        //   max(0, k+s) = k+s (since k>=0, s>=0)
        //   Need l-s >= k+s => l-k >= 2s => s <= (l-k)/2
        //   If l-k < 0, no solutions.
