    // Invalid cases:
    // A >= B + C: a + da >= b + db + c + dc => da - db - dc >= b + c - a
    let k1 = b + c - a;
    let invalid1 = countInvalid(k1, l);

    // B >= A + C: b + db >= a + da + c + dc => db - da - dc >= a + c - b
    let k2 = a + c - b;
    let invalid2 = countInvalid(k2, l);

    // C >= A + B: c + dc >= a + da + b + db => dc - da - db >= a + b - c
    let k3 = a + b - c;
    let invalid3 = countInvalid(k3, l);

    let result = totalWays - invalid1 - invalid2 - invalid3;

    console.log(result);
