        // So t + k <= dx <= l - t
        // This requires t + k <= l - t, i.e., 2t <= l - k, i.e., t <= (l - k) / 2
        // Also t >= 0, and for each t, dy+dz = t has (t+1) solutions.
        // For each valid t, dx can range from t+k to l-t, giving (l-t - (t+k) + 1) = (l - k - 2t + 1) solutions.

        let count = 0;
        let k = other1 + other2 - longStick;

        // t ranges from 0 to floor((l - k) / 2)
        // But we also need t + k >= 0 for dx to be non-negative, which is always true if k >= 0 or t is large enough.
        // Actually dx >= t + k, and dx >= 0, so we need t + k >= 0 or if t+k < 0, then dx >= 0.
        // Wait, dx must be >= max(0, t+k).
        // And dx <= l - t.
        // So number of dx values = max(0, l - t - max(0, t+k) + 1)

        // Let's be more careful.
        // For a given t (where t = dy + dz), the number of (dy, dz) pairs is (t + 1).
        // The constraint is dx >= t + k and dx <= l - t.
        // Also dx >= 0.
        // So lower bound for dx: lo = max(0, t + k)
        // Upper bound for dx: hi = l - t
        // If lo <= hi, then number of dx values = hi - lo + 1.
        // Total for this t: (t + 1) * (hi - lo + 1)

        for (let t = 0; t <= l; t++) {
            let lo = Math.max(0, t + k);
            let hi = l - t;
            if (lo <= hi) {
                count += (t + 1) * (hi - lo + 1);
            }
        }

        return count;
    }

    let total = 0;
    // Total number of ways to distribute at most l
    total = (l + 1) * (l + 2) * (l + 3) / 6;

    // Subtract cases where a is too long
    total -= countWays(a, b, c, l);
    // Subtract cases where b is too long
    total -= countWays(b, a, c, l);
    // Subtract cases where c is too long
    total -= countWays(c, a, b, l);

    console.log(total);
});
