```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const parts = line.split(' ').map(Number);
    const a = parts[0];
    const b = parts[1];
    const c = parts[2];
    const l = parts[3];

    // We need to count the number of triples (da, db, dc) such that:
    // da, db, dc >= 0
    // da + db + dc <= l
    // (a+da), (b+db), (c+dc) form a non-degenerate triangle
    // Triangle inequality: sum of any two > third
    // Let x = a+da, y = b+db, z = c+dc
    // x + y > z, x + z > y, y + z > x

    // Total ways without triangle constraint: number of non-negative integer solutions to da+db+dc <= l
    // That is C(l+3, 3) = (l+3)(l+2)(l+1)/6

    // We need to subtract the cases where triangle inequality fails.
    // Triangle inequality fails if one side >= sum of other two.
    // Since x, y, z are positive, the conditions are:
    // x >= y + z  OR  y >= x + z  OR  z >= x + y
    // These three conditions are mutually exclusive (can't have two at the same time for positive sides).

    // So we count:
    // Count1: number of (da,db,dc) with da+db+dc <= l and a+da >= b+db + c+dc
    // Count2: number of (da,db,dc) with da+db+dc <= l and b+db >= a+da + c+dc
    // Count3: number of (da,db,dc) with da+db+dc <= l and c+dc >= a+da + b+db

    // Answer = total - Count1 - Count2 - Count3

    function countWays(base, other1, other2, l) {
        // Count number of (d_base, d_other1, d_other2) >= 0, d_base + d_other1 + d_other2 <= l
        // such that base + d_base >= other1 + d_other1 + other2 + d_other2
        // Let d1 = d_other1, d2 = d_other2, d0 = d_base
        // Condition: base + d0 >= other1 + d1 + other2 + d2
        // => d0 >= (other1 + other2 - base) + d1 + d2
        // Let k = other1 + other2 - base
        // d0 >= k + d1 + d2
        // Also d0 + d1 + d2 <= l
        // So k + d1 + d2 <= d0 <= l - d1 - d2
        // This requires k + d1 + d2 <= l - d1 - d2
        // => k + 2*d1 + 2*d2 <= l
        // => d1 + d2 <= (l - k) / 2

        // For given d1, d2 with d1+d2 <= floor((l-k)/2), d0 can range from k+d1+d2 to l-d1-d2
        // Number of d0 values = (l - d1 - d2) - (k + d1 + d2) + 1 = l - k - 2*d1 - 2*d2 + 1

        // So we need to sum over d1 >= 0, d2 >= 0, d1+d2 <= floor((l-k)/2) of (l - k - 2*d1 - 2*d2 + 1)
        // Let S = d1 + d2. For a given S, number of (d1,d2) pairs is S+1.
        // Sum = sum_{S=0}^{floor((l-k)/2)} (S+1) * (l - k - 2*S + 1)

        const k = other1 + other2 - base;
        if (k > l) return 0; // No solution possible since d0 >= k + d1 + d2 >= k > l but d0 <= l

        const maxS = Math.floor((l - k) / 2);
        if (maxS < 0) return 0;

        let total = 0;
        for (let S = 0; S <= maxS; S++) {
            const numPairs = S + 1;
            const d0Count = l - k - 2 * S + 1;
            if (d0Count <= 0) break;
            total += numPairs * d0Count;
        }
        return total;
    }

    const total = (l + 1) * (l + 2) * (l + 3) / 6;

    const count1 = countWays(a, b, c, l);
    const count2 = countWays(b, a, c, l);
    const count3 = countWays(c, a, b, l);

    const answer = total - count1 - count2 - count3;

    console.log(answer);
});
